# t6b compared the home-builder listing with the stock image. Those bytes are
# 0xFF there: the builder is Z5 overlay code. This check applies the Z5 CSV
# and compares the listing with that image. It does not edit t6 or t6b.
# Do not edit this file after it has run.
import csv
from pathlib import Path

ROOT = Path('.')
IMAGE = ROOT / 'inputs/00_0100_50000020.decoded.bin'
BASE = 0x60021020
HOME_LISTING = ROOT / 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/disasm-home-k1.txt'
Z5_CSV = ROOT / 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes-c1.csv'
OUT = ROOT / 'work/out/listing-check-t6c.txt'


def parse_listing(path):
    rows = []
    for line in path.read_text(encoding='utf-8').splitlines():
        if not line.strip() or line.startswith('??'):
            continue
        parts = line.split('\t')
        if len(parts) < 2:
            continue
        raw = parts[1].strip()
        if any(c not in '0123456789abcdefABCDEF' for c in raw):
            continue
        rows.append((int(parts[0], 16), bytes.fromhex(raw), parts[2].strip() if len(parts) > 2 else ''))
    return rows


def main():
    image = bytearray(IMAGE.read_bytes())
    proposed = {}
    sources = {}
    with Z5_CSV.open(encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            addr = int(row['runtime_address'], 16)
            off = int(row['component_offset'], 16)
            stock = int(row['stock_byte'], 16)
            neu = int(row['proposed_byte'], 16)
            if image[off] != stock:
                raise SystemExit(f'stock mismatch {addr:#x}')
            image[off] = neu
            proposed[addr] = neu
            sources[addr] = row['source']
    home = parse_listing(HOME_LISTING)
    swap_at = 0x60A8F708
    bad = []
    from_csv = 0
    from_ff = 0
    for addr, raw, text in home:
        if swap_at <= addr < swap_at + 20:
            continue
        for i, b in enumerate(raw):
            got = image[addr - BASE + i]
            if got != b:
                bad.append((hex(addr), raw.hex(), text))
                break
            if (addr + i) in proposed:
                from_csv += 1
            else:
                from_ff += 1
    lines = [
        f'home instructions {len(home)} mismatches {len(bad)}',
        f'listing bytes covered by Z5 rows {from_csv}',
        f'listing bytes not in the Z5 CSV {from_ff}',
    ]
    for row in bad[:8]:
        lines.append('MISMATCH ' + ' '.join(row))
    # The 20-byte swap is the part of the listing the CSV replaced.
    swap_at = 0x60A8F708
    listed = b''.join(raw for addr, raw, _ in home if swap_at <= addr < swap_at + 20)
    over = bytes(image[swap_at - BASE:swap_at - BASE + 20])
    lines.append('listing swap window ' + listed.hex())
    lines.append('overlay swap window ' + over.hex())
    lines.append('swap differs from the pre-swap listing ' + str(listed != over))
    window = image[0x60A8F6BB - BASE:0x60A8F7D5 - BASE]
    base = 0x60A8F6BB
    for name, pat in (
        ('0x9fa1', bytes.fromhex('a19f0000')),
        ('0xdfa1', bytes.fromhex('a1df0000')),
        ('0x99d2', bytes.fromhex('d2990000')),
        ('0x1e01', bytes.fromhex('011e0000')),
        ('0x5962', bytes.fromhex('62590000')),
        ('0x88b2', bytes.fromhex('b2880000')),
        ('0x1dd1', bytes.fromhex('d11d0000')),
        ('0x9a41', bytes.fromhex('419a0000')),
    ):
        hits = []
        start = 0
        while True:
            i = window.find(pat, start)
            if i < 0:
                break
            hits.append(hex(base + i))
            start = i + 1
        lines.append(f'overlay builder {name} {hits or "none"}')
    text = '\n'.join(lines) + '\n'
    OUT.write_text(text, encoding='utf-8')
    print(text, end='')
    if bad:
        raise SystemExit(1)


if __name__ == '__main__':
    main()
